import{_ as o,o as t,c as e,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const h=JSON.parse('{"title":"国密 SM2 / SM4 在纯前端怎么做","description":"","frontmatter":{"title":"国密 SM2 / SM4 在纯前端怎么做"},"headers":[],"relativePath":"md/tools/crypto.md","filePath":"md/tools/crypto.md","lastUpdated":1795424423000}'),s={name:"md/tools/crypto.md"};function l(c,a,n,d,i,p){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="国密-sm2-sm4-在纯前端怎么做" tabindex="-1">国密 SM2 / SM4 在纯前端怎么做 <a class="header-anchor" href="#国密-sm2-sm4-在纯前端怎么做" aria-label="Permalink to &quot;国密 SM2 / SM4 在纯前端怎么做&quot;">​</a></h1><p>国密算法工具站的典型形态：用户粘贴一段密文、一把密钥，浏览器里算完直接显示结果，服务端什么都不留。</p><p>技术上完全可行，但有几个地方做错就会得到一个&quot;看起来能用、实际上换个人解密就失败&quot;的工具。</p><h2 id="sm2-非对称-别把它当-rsa-用" tabindex="-1">SM2：非对称，别把它当 RSA 用 <a class="header-anchor" href="#sm2-非对称-别把它当-rsa-用" aria-label="Permalink to &quot;SM2：非对称，别把它当 RSA 用&quot;">​</a></h2><p>SM2 是椭圆曲线公钥算法，能做签名和加密。三个最容易踩的点：</p><h3 id="_1-密文格式有-c1c2c3-和-c1c3c2-两种顺序" tabindex="-1">1. 密文格式有 C1C2C3 和 C1C3C2 两种顺序 <a class="header-anchor" href="#_1-密文格式有-c1c2c3-和-c1c3c2-两种顺序" aria-label="Permalink to &quot;1. 密文格式有 C1C2C3 和 C1C3C2 两种顺序&quot;">​</a></h3><p>这是互操作性问题的第一大来源。老版实现（包括部分库的默认行为）输出 <code>C1C3C2</code>，国密标准要求 <code>C1C2C3</code>。</p><p>症状很典型：自己加密自己解密完全正常，跟别人的系统对接就报错。<strong>解密端必须先问清楚对方是哪种顺序，工具里最好提供一个格式开关</strong>，两种都支持。</p><p>还有 C1 点是否带 <code>04</code> 前缀的问题。压缩点的表示里 <code>04</code> 表示非压缩，某些实现输出的密文包含它，某些不包含。跨系统对接时这也是必查项。</p><h3 id="_2-随机数必须来自密码学安全的源" tabindex="-1">2. 随机数必须来自密码学安全的源 <a class="header-anchor" href="#_2-随机数必须来自密码学安全的源" aria-label="Permalink to &quot;2. 随机数必须来自密码学安全的源&quot;">​</a></h3><p>SM2 加密过程依赖随机数 k。用 <code>Math.random()</code> 生成 k，会得到一个<strong>能通过自测、但密码学上已经破了</strong>的实现。浏览器里要用 <code>crypto.getRandomValues</code>。</p><p>同理，密钥生成也不能用普通随机。私钥的熵不足，暴力搜索的成本会从&quot;不可能&quot;降到&quot;可行&quot;。</p><h3 id="_3-私钥别碰服务端" tabindex="-1">3. 私钥别碰服务端 <a class="header-anchor" href="#_3-私钥别碰服务端" aria-label="Permalink to &quot;3. 私钥别碰服务端&quot;">​</a></h3><p>纯前端做 SM2 的最实际价值就在这里：私钥只在浏览器内存里存在，不经过网络、不落盘、不进日志。</p><p>对应要做的两件事：</p><ul><li>刷新页面即清空（不要用 localStorage 存私钥，那是把风险从服务端搬到本地）</li><li>不要把输入内容拼进任何请求 URL 或错误上报里</li></ul><h2 id="sm4-分组密码-模式比算法更容易错" tabindex="-1">SM4：分组密码，模式比算法更容易错 <a class="header-anchor" href="#sm4-分组密码-模式比算法更容易错" aria-label="Permalink to &quot;SM4：分组密码，模式比算法更容易错&quot;">​</a></h2><p>SM4 是 128 位分组、128 位密钥的分组密码。算法本身没什么选择空间，但<strong>使用模式</strong>选择很多，而模式决定了互操作性。</p><p>要点：</p><ul><li><strong>默认用 CBC + PKCS7 填充</strong>，这是国内系统里最常见的组合。ECB 不要作为默认选项（相同明文块产生相同密文，会泄露结构），但可以留一个&quot;兼容旧系统&quot;的入口。</li><li><strong>IV 的处理方式要明确</strong>。常见做法是把 IV 明文拼在密文前面，解密端取前 16 字节。如果对方是固定 IV，要显式标注这是不安全用法。</li><li><strong>编码要能对上</strong>。密文输出 Base64 还是 Hex、是否大写、是否带换行和空格，任何一项不一致都会让对接方以为&quot;算法不对&quot;。</li></ul><h2 id="一个工具站的正确姿势" tabindex="-1">一个工具站的正确姿势 <a class="header-anchor" href="#一个工具站的正确姿势" aria-label="Permalink to &quot;一个工具站的正确姿势&quot;">​</a></h2><p>界面按&quot;输入区 / 参数区 / 结果区&quot;三段走，参数区默认值取最常见组合，并提供&quot;高级&quot;展开。</p><p>比界面更重要的是<strong>正反验证</strong>：加密完成后，提供一个&quot;用这段密文解回去&quot;的按钮。用户不需要理解算法，只需要看到&quot;能回来&quot;就能确认工具是对的。这比写十段算法说明有用。</p><h2 id="前端能不能算得动" tabindex="-1">前端能不能算得动 <a class="header-anchor" href="#前端能不能算得动" aria-label="Permalink to &quot;前端能不能算得动&quot;">​</a></h2><p>能。SM4 加密一段几 KB 的文本，浏览器里是毫秒级。真正需要担心的不是性能，而是<strong>大文件</strong>：超过几 MB 时逐块处理要注意内存峰值，用流式或分块加解密，避免一次性把整个字符串摊在内存里。</p><p>SM2 的性能要弱一些（椭圆曲线运算），但它本来就不是拿来加密大段数据的用途——正确用法是&quot;SM2 加密一个对称密钥，SM4 加密正文&quot;。工具站上应该把这层语义讲清楚，否则用户会拿 SM2 去加密整篇文章，然后抱怨慢。</p>',26)])])}const q=o(s,[["render",l]]);export{h as __pageData,q as default};
